     1	/**
     2	 * ALE-381: the Intake page's automatic payment start. Phoenix takes the Seat Hold and
     3	 * creates (or reuses) the embedded Stripe Checkout Session. Only a hosted
     4	 * hold created before the migration still redirects. A refusal answers
     5	 * its detail, and the page reloads Phoenix's view.
     6	 *
     7	 * ALE-388: a Carried Fee holder confirms instead. Phoenix takes the seat in
     8	 * one transaction (no Stripe); the form's success reloads the page, which
     9	 * then shows Phoenix's `paid` (or `full`) view.
    10	 */
    11	import { form, getRequestEvent } from "$app/server";
    12	import { redirect } from "@sveltejs/kit";
    13	import {
    14		beginnersWorkshopIntakeConfirm,
    15		beginnersWorkshopIntakeStartPayment,
    16	} from "@dhc/api-client";
    17	import { apiProblem } from "#lib/api-error.js";
    18	import { intakePaymentSchema } from "#lib/schemas/beginnersIntake.js";
    19	import { apiClientOptions } from "#lib/server/api-client.js";
    20	
    21	export const startIntakePayment = form(
    22		intakePaymentSchema,
    23		async ({ token }) => {
    24			const response = await beginnersWorkshopIntakeStartPayment({
    25				...apiClientOptions(getRequestEvent().cookies),
    26				path: { token },
    27			});
    28	
    29			if (response.data) {
    30				const { checkoutUrl, clientSecret, sessionId } = response.data.data;
    31				if (checkoutUrl) redirect(303, checkoutUrl, { external: true });
    32				if (clientSecret && sessionId) {
    33					return { ok: true as const, clientSecret, sessionId };
    34				}
    35			}
    36	
    37			return {
    38				ok: false as const,
    39				error:
    40					apiProblem(response.error)?.detail ??
    41					"Payment is unavailable right now. Please try again shortly.",
    42			};
    43		},
    44	);
    45	
    46	export const confirmIntakePlace = form(
    47		intakePaymentSchema,
    48		async ({ token }) => {
    49			const response = await beginnersWorkshopIntakeConfirm({
    50				...apiClientOptions(getRequestEvent().cookies),
    51				path: { token },
    52			});
    53	
    54			if (response.data) return { ok: true as const };
    55	
    56			return {
    57				ok: false as const,
    58				error:
    59					apiProblem(response.error)?.detail ??
    60					"We couldn't confirm your place right now. Please try again shortly.",
    61			};
    62		},
    63	);
