    10	/**
    11	 * Load function for public workshop registration page.
    12	 *
    13	 * This implements the gating logic described in Stage 3B:
    14	 * - Validates workshop ID as UUID
    15	 * - Fetches gate state from registration service
    16	 * - Returns 404 for unavailable workshops
    17	 * - Redirects full workshops to /workshops/[id]/full
    18	 * - Returns workshop payload for eligible workshops
    19	 */
    20	export const load: PageServerLoad = async ({ params, url }) => {
    21		// Validate workshop ID
    22		const workshopIdResult = v.safeParse(v.pipe(v.string(), v.uuid()), params.id);
    23	
    24		if (!workshopIdResult.success) {
    25			error(404, "Workshop not found");
    26		}
    27	
    28		const workshopId = workshopIdResult.output;
    29	
    30		// Check eligibility using public registration service
    31		const gateStatus = await getExternalWorkshopRegistrationGate(workshopId);
    32	
    33		// Handle different gate states according to Stage 3B contract
    34		if (!gateStatus.canRegister) {
    35			switch (gateStatus.reason) {
    36				case "NOT_FOUND":
    37				case "NOT_PUBLISHED":
    38				case "NOT_PUBLIC":
    39				case "NO_EXTERNAL_PRICE":
    40					// These states return 404 - workshop unavailable for registration
    41					error(404, "Workshop not found");
    42					break;
    43	
    44				case "FULL":
    45					redirect(303, `/workshops/${workshopId}/full`);
    46			}
    47		}
    48	
    49		const returnUrl = `${url.origin}/workshops/${workshopId}/confirmation?session_id={CHECKOUT_SESSION_ID}`;
    50	
    51		try {
    52			const checkoutSession = await createExternalWorkshopCheckoutSession(
    53				workshopId,
    54				crypto.randomUUID(),
    55				returnUrl,
    56			);
    57			const workshop = gateStatus.workshop;
    58			if (!workshop) error(404, "Workshop not found");
    59	
    60			return {
    61				workshop: {
    62					id: workshop.id,
    63					title: workshop.title,
    64					description: workshop.description,
    65					start_date: workshop.startDate,
    66					end_date: workshop.endDate,
    67					location: workshop.location,
    68					price_non_member: workshop.priceNonMember,
    69					max_capacity: workshop.maxCapacity,
    70				},
    71				checkoutSessionId: checkoutSession.checkoutSessionId,
    72				checkoutClientSecret: checkoutSession.checkoutClientSecret,
    73			};
    74		} catch (err) {
    75			if (err instanceof ExternalWorkshopRegistrationApiError) {
    76				if (err.code === "WORKSHOP_FULL") {
    77					redirect(303, `/workshops/${workshopId}/full`);
    78				}
    79	
    80				if (err.code === "WORKSHOP_NOT_FOUND") {
    81					error(404, "Workshop not found");
    82				}
    83			}
    84	
    85			throw err;
    86		}
    87	};

