import type {
	StripeEmbeddedCheckout,
	StripeEmbeddedCheckoutOptions,
} from "@stripe/stripe-js";
import { fromCallback } from "xstate";

/**
 * The Stripe embedded Checkout widget as an XState callback actor (ALE-447).
 *
 * The actor's lifetime is the widget's lifetime: it creates the widget when
 * it starts, mounts it, reports what happened, and destroys it when it stops.
 * A machine that invokes it in the state where payment is collected therefore
 * destroys the widget by leaving that state, and a widget that resolves after
 * the actor stopped is destroyed instead of mounted. Callbacks arriving after
 * the stop are dropped.
 *
 * This is an SDK adapter only. Each domain keeps its own machine and decides
 * what a failure or a completion means; never grow this into a checkout flow.
 */

export type EmbeddedCheckoutWidget = Pick<
	StripeEmbeddedCheckout,
	"mount" | "destroy"
>;

/** Creates the widget for one Checkout Session; injected so tests need no Stripe. */
export type EmbeddedCheckoutFactory = (
	options: StripeEmbeddedCheckoutOptions,
) => Promise<EmbeddedCheckoutWidget>;

/** What the widget actor reports to the machine that invoked it. */
export type EmbeddedCheckoutWidgetEvent =
	| { type: "WIDGET.MOUNTED" }
	| { type: "WIDGET.COMPLETED" }
	| { type: "WIDGET.FAILED"; error: unknown };

export type EmbeddedCheckoutWidgetInput = { clientSecret: string };

/**
 * Builds the widget actor. `container` is read when the widget resolves, so
 * the host's element binding may arrive after the actor starts.
 */
export function embeddedCheckoutWidget(
	create: EmbeddedCheckoutFactory,
	container: () => HTMLElement | undefined,
) {
	return fromCallback<
		{ type: "WIDGET.NONE" },
		EmbeddedCheckoutWidgetInput,
		EmbeddedCheckoutWidgetEvent
	>(({ input, sendBack }) => {
		let stopped = false;
		let widget: EmbeddedCheckoutWidget | undefined;
		const report = (event: EmbeddedCheckoutWidgetEvent) => {
			if (!stopped) sendBack(event);
		};

		void (async () => {
			try {
				const created = await create({
					clientSecret: input.clientSecret,
					onComplete: () => report({ type: "WIDGET.COMPLETED" }),
				});
				if (stopped) {
					created.destroy();
					return;
				}
				widget = created;
				const element = container();
				if (!element) throw new Error("Checkout container is missing");
				created.mount(element);
				report({ type: "WIDGET.MOUNTED" });
			} catch (error) {
				// The machine leaves the collecting state on failure, which stops
				// this actor and destroys any widget created before the failure.
				report({ type: "WIDGET.FAILED", error });
			}
		})();

		return () => {
			stopped = true;
			widget?.destroy();
			widget = undefined;
		};
	});
}

input.newString:
		return () => {
			stopped = true;
			widget?.destroy();
			widget = undefined;
		};
		},
	);
}

input.oldString:
		return () => {
			stopped = true;
			widget?.destroy();
			widget = undefined;
		};
	});
}

