import { fromPromise, setup } from "xstate";
import type {
	EmbeddedCheckoutWidgetEvent,
	EmbeddedCheckoutWidgetInput,
} from "#lib/stripe/embedded-checkout-widget.js";
import { embeddedCheckoutWidget } from "#lib/stripe/embedded-checkout-widget.js";

/**
 * The Intake page's embedded Checkout widget (ALE-447), one actor per
 * `IntakeCheckout` instance (`useMachine`; never a module-scope actor).
 *
 * `collecting` invokes the widget actor, so the Stripe widget exists only
 * while payment is being collected. Stripe's completion callback moves to
 * `confirming`, which leaves `collecting` and so destroys the widget before
 * Phoenix is asked for the outcome. `confirmFailed` retries only the
 * confirmation: nothing leads from confirmation back to `collecting`, so a
 * person who has paid can never be shown payment collection again. Phoenix
 * decides whether the place is paid; Stripe's browser callback never does.
 *
 * Failure copy is fixed: Stripe errors may contain credentials, so they are
 * never shown or logged.
 */

export type IntakeCheckoutInput = { clientSecret: string };

export type IntakeCheckoutEvent =
	| EmbeddedCheckoutWidgetEvent
	| { type: "RETRY" };

export const intakeCheckoutMachine = setup({
	// SAFETY: `setup({ types })` reads only the types of these placeholders.
	types: {
		context: {} as IntakeCheckoutInput,
		events: {} as IntakeCheckoutEvent,
		input: {} as IntakeCheckoutInput,
	},
	actors: {
		// The host provides both: the widget through `embeddedCheckoutWidget`
		// with its own factory and container, and Phoenix's confirmation.
		widget: embeddedCheckoutWidget(async () => {
			throw new Error("widget must be provided by the host");
		}, () => undefined),
		confirm: fromPromise<void, void>(async () => {
			throw new Error("confirm must be provided by the host");
		}),
	},
}).createMachine({
	id: "intakeCheckout",
	context: ({ input }) => ({ clientSecret: input.clientSecret }),
	initial: "collecting",
	states: {
		collecting: {
			invoke: {
				src: "widget",
				input: ({ context }): EmbeddedCheckoutWidgetInput => ({
					clientSecret: context.clientSecret,
				}),
			},
			on: {
				"WIDGET.FAILED": { target: "initFailed" },
				"WIDGET.COMPLETED": { target: "confirming" },
			},
			initial: "loading",
			states: {
				loading: { on: { "WIDGET.MOUNTED": { target: "active" } } },
				active: {},
			},
		},
		// Retrying initialization reuses the same Checkout Session: it never
		// starts another payment.
		initFailed: { on: { RETRY: { target: "collecting" } } },
		confirming: {
			invoke: {
				src: "confirm",
				onDone: { target: "confirmed" },
				onError: { target: "confirmFailed" },
			},
		},
		confirmFailed: { on: { RETRY: { target: "confirming" } } },
		// Phoenix answered; the page now shows its view.
		confirmed: { type: "final" },
	},
});

export type IntakeCheckoutPhase =
	| "loading"
	| "active"
	| "initFailed"
	| "confirming"
	| "confirmFailed"
	| "confirmed";

export type IntakeCheckoutPresentation = {
	/** The status line while something is in flight, if any. */
	status: string | null;
	/** Fixed failure copy, if the phase failed. */
	failure: string | null;
	/** The retry control's label, if the phase offers one. */
	retry: string | null;
};

/** One intentional presentation per phase; adding a phase is a type error here. */
export const intakeCheckoutPresentation = {
	loading: { status: "Loading secure payment…", failure: null, retry: null },
	active: { status: null, failure: null, retry: null },
	initFailed: {
		status: null,
		failure: "We couldn't load secure payment. Please try again.",
		retry: "Try again",
	},
	confirming: {
		status: "Confirming your payment…",
		failure: null,
		retry: null,
	},
	confirmFailed: {
		status: null,
		failure:
			"We couldn't check your payment yet. Check again — don't pay twice.",
		retry: "Check payment",
	},
	confirmed: { status: null, failure: null, retry: null },
} satisfies Record<IntakeCheckoutPhase, IntakeCheckoutPresentation>;

/** The leaf phase of a snapshot of `intakeCheckoutMachine`. */
export function intakeCheckoutPhase(snapshot: {
	matches: (value: never) => boolean;
	value: unknown;
}): IntakeCheckoutPhase {
	const value = snapshot.value;
	if (typeof value === "string") return value as IntakeCheckoutPhase;
	// SAFETY: `collecting` is the one compound state; its children are leaves.
	return (value as { collecting: "loading" | "active" }).collecting;
}

