/**
 * ALE-447: the Intake page's payment orchestration, one actor per Intake
 * page instance (`useMachine`; never a module-scope actor).
 *
 * The phase follows Phoenix's safe view (`page.action` and `page.state`),
 * which the host sends as `PAGE` whenever the load data changes; the machine
 * never infers a payment outcome itself.
 *
 * - `payment`: opening the link starts payment automatically, once per
 *   instance, as the browser POST that takes the Seat Hold (the page's GET
 *   never does). Phoenix resumes a live hold's session rather than creating
 *   another. A refusal shows Phoenix's detail, an unexpected failure fixed
 *   copy, and both offer a manual retry. If Phoenix's view returns to a
 *   payment action after the automatic start was spent, the person starts
 *   again by hand (`paused`); the page never POSTs twice on its own.
 *   `checkout` hands the session to the embedded widget, whose own machine
 *   owns collection and confirmation.
 * - `confirmPlace`: a Carried Fee holder confirms instead of paying. The
 *   remote form owns that submission; this phase only selects it.
 * - `awaitingPayment`: `payment_in_progress` asks Phoenix again after
 *   `refreshMs`, re-armed by every new view, until it reports another state.
 * - `settled`: every other view; its one action (Check again) asks Phoenix.
 */
import type { BeginnersIntakePage } from "@dhc/api-client";
import { assign, fromPromise, setup, type SnapshotFrom } from "xstate";
import {
	confirmsWithCarriedFee,
	startsCheckout,
} from "#lib/beginners-workshops/intake-page.js";

/** What the start-payment POST answers; `undefined` while it redirects away. */
export type IntakePaymentStart =
	| { ok: true; clientSecret: string; sessionId: string }
	| { ok: false; error: string }
	| undefined;

export type IntakeCheckoutSession = { clientSecret: string; sessionId: string };

export type IntakePageInput = { page: BeginnersIntakePage; refreshMs: number };

export type IntakePageContext = IntakePageInput & {
	/** Whether this instance has spent its one automatic start. */
	started: boolean;
	session: IntakeCheckoutSession | null;
	/** Why the last start did not open payment, worded for the person. */
	refusal: string | null;
};

export type IntakePageEvent =
	| { type: "PAGE"; page: BeginnersIntakePage }
	| { type: "RETRY" }
	| { type: "REFRESH" };

export const START_FAILED =
	"Payment is unavailable right now. Please try again shortly.";

export const intakePageMachine = setup({
	// SAFETY: `setup({ types })` reads only the types of these placeholders.
	types: {
		context: {} as IntakePageContext,
		events: {} as IntakePageEvent,
		input: {} as IntakePageInput,
	},
	actors: {
		startPayment: fromPromise<IntakePaymentStart, void>(async () => {
			throw new Error("startPayment must be provided by the host");
		}),
	},
	actions: {
		refresh: () => {},
		adoptPage: assign({
			page: ({ context, event }) =>
				event.type === "PAGE" ? event.page : context.page,
		}),
	},
	guards: {
		newPage: ({ context, event }) =>
			event.type === "PAGE" && event.page !== context.page,
		newPageStillPays: ({ context, event }) =>
			event.type === "PAGE" &&
			event.page !== context.page &&
			startsCheckout(event.page),
		pays: ({ context }) => startsCheckout(context.page),
		startSpent: ({ context }) => context.started,
		confirms: ({ context }) => confirmsWithCarriedFee(context.page),
		paymentInProgress: ({ context }) =>
			context.page.state === "payment_in_progress",
	},
	delays: {
		refreshDelay: ({ context }) => context.refreshMs,
	},
}).createMachine({
	id: "intakePage",
	context: ({ input }) => ({
		...input,
		started: false,
		session: null,
		refusal: null,
	}),
	initial: "routing",
	on: {
		PAGE: { guard: "newPage", target: ".routing", actions: "adoptPage" },
	},
	states: {
		routing: {
			always: [
				{ guard: "pays", target: "payment" },
				{ guard: "confirms", target: "confirmPlace" },
				{ guard: "paymentInProgress", target: "awaitingPayment" },
				{ target: "settled" },
			],
		},
		payment: {
			// A fresh view that still pays (a live hold after the POST) keeps
			// the session and the widget where they are.
			on: {
				PAGE: [
					{ guard: "newPageStillPays", actions: "adoptPage" },
					{ guard: "newPage", target: "routing", actions: "adoptPage" },
				],
			},
			initial: "deciding",
			states: {
				deciding: {
					always: [
						{ guard: "startSpent", target: "paused" },
						{ target: "starting" },
					],
				},
				starting: {
					entry: assign({ started: true }),
					invoke: {
						src: "startPayment",
						onDone: [
							{
								guard: ({ event }) => event.output?.ok === true,
								target: "checkout",
								actions: assign({
									session: ({ event }) =>
										event.output?.ok
											? {
													clientSecret: event.output.clientSecret,
													sessionId: event.output.sessionId,
												}
											: null,
									refusal: null,
								}),
							},
							{
								guard: ({ event }) => event.output?.ok === false,
								target: "refused",
								actions: assign({
									refusal: ({ event }) =>
										event.output?.ok === false ? event.output.error : null,
								}),
							},
							// A hold created before the embedded migration is
							// redirected to hosted Checkout; the page is leaving.
							{ target: "redirecting" },
						],
						onError: {
							target: "refused",
							actions: assign({ refusal: START_FAILED }),
						},
					},
				},
				checkout: {},
				refused: { on: { RETRY: { target: "starting" } } },
				paused: { on: { RETRY: { target: "starting" } } },
				redirecting: {},
			},
		},
		confirmPlace: {},
		awaitingPayment: {
			on: { REFRESH: { actions: "refresh" } },
			after: { refreshDelay: { actions: "refresh" } },
		},
		settled: {
			on: { REFRESH: { actions: "refresh" } },
		},
	},
});

export type IntakePagePhase =
	| "starting"
	| "checkout"
	| "refused"
	| "paused"
	| "redirecting"
	| "confirmPlace"
	| "awaitingPayment"
	| "settled";

/** The leaf phase of a snapshot of `intakePageMachine`. */
export function intakePagePhase(
	snapshot: SnapshotFrom<typeof intakePageMachine>,
): IntakePagePhase {
	for (const phase of [
		"starting",
		"checkout",
		"refused",
		"paused",
		"redirecting",
	] as const) {
		if (snapshot.matches({ payment: phase })) return phase;
	}
	if (snapshot.matches("confirmPlace")) return "confirmPlace";
	if (snapshot.matches("awaitingPayment")) return "awaitingPayment";
	// `routing` and `payment.deciding` are transient and never observed.
	return "settled";
}

