import type { StripeEmbeddedCheckoutOptions } from "@stripe/stripe-js";
import { describe, expect, it, vi } from "vitest";
import { createActor, createMachine, type AnyEventObject } from "xstate";
import {
	embeddedCheckoutWidget,
	type EmbeddedCheckoutWidget,
} from "./embedded-checkout-widget";

function deferred<T>() {
	let resolve!: (value: T) => void;
	let reject!: (error: unknown) => void;
	const promise = new Promise<T>((res, rej) => {
		resolve = res;
		reject = rej;
	});
	return { promise, resolve, reject };
}

function fakeWidget(): EmbeddedCheckoutWidget & {
	mount: ReturnType<typeof vi.fn>;
	destroy: ReturnType<typeof vi.fn>;
} {
	return { mount: vi.fn(), destroy: vi.fn() };
}

// SAFETY: the adapter only hands the container to the fake widget's `mount`.
const container = {} as HTMLElement;

/** Runs the widget actor under a parent that records what it reports. */
function harness(
	create: (options: StripeEmbeddedCheckoutOptions) => Promise<EmbeddedCheckoutWidget>,
	getContainer: () => HTMLElement | undefined = () => container,
) {
	const reported: AnyEventObject[] = [];
	const factory = vi.fn(create);
	const parent = createActor(
		createMachine({
			invoke: {
				src: embeddedCheckoutWidget(factory, getContainer),
				input: { clientSecret: "cs_test_secret" },
			},
			on: { "*": { actions: ({ event }) => reported.push(event) } },
		}),
	);
	return { parent, factory, reported };
}

describe("embeddedCheckoutWidget", () => {
	it("creates the widget for the session, mounts it, and reports it mounted", async () => {
		const widget = fakeWidget();
		const { parent, factory, reported } = harness(async () => widget);
		parent.start();

		await vi.waitFor(() =>
			expect(reported).toContainEqual({ type: "WIDGET.MOUNTED" }),
		);
		expect(factory.mock.calls[0][0].clientSecret).toBe("cs_test_secret");
		expect(widget.mount).toHaveBeenCalledWith(container);
		expect(widget.destroy).not.toHaveBeenCalled();
	});

	it("forwards Stripe's completion callback while it runs", async () => {
		const widget = fakeWidget();
		const { parent, factory, reported } = harness(async () => widget);
		parent.start();
		await vi.waitFor(() => expect(widget.mount).toHaveBeenCalledOnce());

		factory.mock.calls[0][0].onComplete?.();
		expect(reported).toContainEqual({ type: "WIDGET.COMPLETED" });
	});

	it("destroys the widget when stopped and drops a later completion", async () => {
		const widget = fakeWidget();
		const { parent, factory, reported } = harness(async () => widget);
		parent.start();
		await vi.waitFor(() => expect(widget.mount).toHaveBeenCalledOnce());

		parent.stop();
		expect(widget.destroy).toHaveBeenCalledOnce();
		factory.mock.calls[0][0].onComplete?.();
		expect(reported).not.toContainEqual({ type: "WIDGET.COMPLETED" });
	});

	it("destroys a widget that resolves after the stop instead of mounting it", async () => {
		const widget = fakeWidget();
		const late = deferred<EmbeddedCheckoutWidget>();
		const { parent, reported } = harness(() => late.promise);
		parent.start();

		parent.stop();
		late.resolve(widget);
		await vi.waitFor(() => expect(widget.destroy).toHaveBeenCalledOnce());
		expect(widget.mount).not.toHaveBeenCalled();
		expect(reported).toHaveLength(0);
	});

	it("reports a factory failure with the error, and nothing after a stop", async () => {
		const failing = deferred<EmbeddedCheckoutWidget>();
		const { parent, reported } = harness(() => failing.promise);
		parent.start();
		const error = new Error("Stripe unavailable");
		failing.reject(error);
		await vi.waitFor(() =>
			expect(reported).toContainEqual({ type: "WIDGET.FAILED", error }),
		);

		const second = deferred<EmbeddedCheckoutWidget>();
		const stopped = harness(() => second.promise);
		stopped.parent.start();
		stopped.parent.stop();
		second.reject(new Error("late"));
		await Promise.resolve();
		expect(stopped.reported).toHaveLength(0);
	});

	it("a widget that fails to mount is reported and destroyed with the actor", async () => {
		const widget = fakeWidget();
		const { parent, reported } = harness(
			async () => widget,
			() => undefined,
		);
		parent.start();
		await vi.waitFor(() =>
			expect(reported.map((event) => event.type)).toEqual(["WIDGET.FAILED"]),
		);

		parent.stop();
		expect(widget.destroy).toHaveBeenCalledOnce();
	});
});

