import type { StripeEmbeddedCheckoutOptions } from "@stripe/stripe-js";
import { describe, expect, it, vi } from "vitest";
import { createActor, fromPromise, waitFor } from "xstate";
import {
	embeddedCheckoutWidget,
	type EmbeddedCheckoutWidget,
} from "#lib/stripe/embedded-checkout-widget.js";
import {
	intakeCheckoutMachine,
	intakeCheckoutPhase,
} from "./intake-checkout-machine";

function deferred<T>() {
	let resolve!: (value: T) => void;
	let reject!: (error: unknown) => void;
	const promise = new Promise<T>((res, rej) => {
		resolve = res;
		reject = rej;
	});
	return { promise, resolve, reject };
}

// SAFETY: only the fake widget's `mount` receives the container.
const container = {} as HTMLElement;

function harness(
	options: {
		create?: (
			options: StripeEmbeddedCheckoutOptions,
		) => Promise<EmbeddedCheckoutWidget>;
		confirm?: () => Promise<void>;
	} = {},
) {
	const widget = { mount: vi.fn(), destroy: vi.fn() };
	const create = vi.fn(options.create ?? (async () => widget));
	const confirm = vi.fn(options.confirm ?? (async () => {}));
	const actor = createActor(
		intakeCheckoutMachine.provide({
			actors: {
				widget: embeddedCheckoutWidget(create, () => container),
				confirm: fromPromise(() => confirm()),
			},
		}),
		{ input: { clientSecret: "cs_test_secret" } },
	);
	const phase = () => intakeCheckoutPhase(actor.getSnapshot());
	const completeInStripe = () => create.mock.lastCall?.[0].onComplete?.();
	return { actor, widget, create, confirm, phase, completeInStripe };
}

describe("intakeCheckoutMachine", () => {
	it("creates nothing until the host is mounted in the browser", () => {
		const { actor, create, phase } = harness();
		actor.start();

		expect(phase()).toBe("loading");
		expect(create).not.toHaveBeenCalled();
	});

	it("mounts the session's widget, then confirms with Phoenix once Stripe completes", async () => {
		const { actor, widget, create, confirm, phase, completeInStripe } =
			harness();
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		expect(create.mock.calls[0][0].clientSecret).toBe("cs_test_secret");
		expect(widget.mount).toHaveBeenCalledWith(container);
		expect(confirm).not.toHaveBeenCalled();

		completeInStripe();
		expect(phase()).toBe("confirming");
		// Payment collection is gone before Phoenix is asked.
		expect(widget.destroy).toHaveBeenCalledOnce();
		await waitFor(actor, (s) => s.matches("confirmed"));
		expect(confirm).toHaveBeenCalledOnce();
	});

	it("an initialization failure retries initialization with the same session", async () => {
		const widget = { mount: vi.fn(), destroy: vi.fn() };
		const create = vi
			.fn<(o: StripeEmbeddedCheckoutOptions) => Promise<typeof widget>>()
			.mockRejectedValueOnce(new Error("cs_test_secret"))
			.mockResolvedValue(widget);
		const { actor, phase } = harness({ create });
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches("initFailed"));

		actor.send({ type: "RETRY" });
		expect(phase()).toBe("loading");
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		expect(create).toHaveBeenCalledTimes(2);
		expect(create.mock.calls[1][0].clientSecret).toBe("cs_test_secret");
	});

	it("a confirmation failure retries only the confirmation, never collection", async () => {
		const confirm = vi
			.fn<() => Promise<void>>()
			.mockRejectedValueOnce(new Error("network"))
			.mockResolvedValue(undefined);
		const { actor, create, phase, completeInStripe } = harness({ confirm });
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		completeInStripe();
		await waitFor(actor, (s) => s.matches("confirmFailed"));

		// Nothing from here reaches payment collection.
		expect(actor.getSnapshot().can({ type: "WIDGET.MOUNTED" })).toBe(false);
		actor.send({ type: "MOUNTED" });
		actor.send({ type: "WIDGET.FAILED", error: new Error("late") });
		expect(phase()).toBe("confirmFailed");

		actor.send({ type: "RETRY" });
		expect(phase()).toBe("confirming");
		await waitFor(actor, (s) => s.matches("confirmed"));
		expect(confirm).toHaveBeenCalledTimes(2);
		expect(create).toHaveBeenCalledOnce();
	});

	it("repeated completions and retries while confirming ask Phoenix once", async () => {
		const answer = deferred<void>();
		const { actor, confirm, completeInStripe } = harness({
			confirm: () => answer.promise,
		});
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));

		completeInStripe();
		completeInStripe();
		actor.send({ type: "WIDGET.COMPLETED" });
		actor.send({ type: "RETRY" });
		answer.resolve();
		await waitFor(actor, (s) => s.matches("confirmed"));
		expect(confirm).toHaveBeenCalledOnce();
	});

	it("stopping mid-initialization destroys the late widget and never mounts it", async () => {
		const widget = { mount: vi.fn(), destroy: vi.fn() };
		const late = deferred<EmbeddedCheckoutWidget>();
		const { actor } = harness({ create: () => late.promise });
		actor.start();
		actor.send({ type: "MOUNTED" });

		actor.stop();
		late.resolve(widget);
		await vi.waitFor(() => expect(widget.destroy).toHaveBeenCalledOnce());
		expect(widget.mount).not.toHaveBeenCalled();
	});

	it("stopping mid-confirmation discards Phoenix's late answer", async () => {
		const answer = deferred<void>();
		const { actor, phase, completeInStripe } = harness({
			confirm: () => answer.promise,
		});
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		completeInStripe();

		actor.stop();
		answer.reject(new Error("network"));
		await Promise.resolve();
		expect(phase()).toBe("confirming");
		expect(actor.getSnapshot().status).toBe("stopped");
	});
});

import type { BeginnersIntakePage } from "@dhc/api-client";
import { describe, expect, it, vi } from "vitest";
import { createActor, fromPromise, SimulatedClock, waitFor } from "xstate";
import {
	intakePageMachine,
	intakePagePhase,
	START_FAILED,
	type IntakePaymentStart,
} from "./intake-page-machine";

function deferred<T>() {
	let resolve!: (value: T) => void;
	let reject!: (error: unknown) => void;
	const promise = new Promise<T>((res, rej) => {
		resolve = res;
		reject = rej;
	});
	return { promise, resolve, reject };
}

function page(overrides: Partial<BeginnersIntakePage> = {}): BeginnersIntakePage {
	return {
		state: "pay",
		action: "pay",
		closedReason: null,
		firstName: "Aoife",
		workshop: {
			date: "2026-11-14",
			startTime: "18:30",
			endTime: null,
			venue: "St. Andrew's Hall",
		},
		feeCents: 4000,
		...overrides,
	};
}

const opened: IntakePaymentStart = {
	ok: true,
	clientSecret: "cs_test_secret",
	sessionId: "cs_test_1",
};

function harness(
	initial: BeginnersIntakePage,
	startPayment: () => Promise<IntakePaymentStart> = async () => opened,
) {
	const start = vi.fn(startPayment);
	const refresh = vi.fn();
	const clock = new SimulatedClock();
	const actor = createActor(
		intakePageMachine.provide({
			actors: { startPayment: fromPromise(() => start()) },
			actions: { refresh: () => refresh() },
		}),
		{ input: { page: initial, refreshMs: 3000 }, clock },
	);
	const phase = () => intakePagePhase(actor.getSnapshot());
	return { actor, start, refresh, clock, phase };
}

describe("intakePageMachine: the automatic payment start", () => {
	it.each(["pay", "continue_payment"] as const)(
		"%s starts payment once the browser has mounted, and only then",
		async (action) => {
			const { actor, start, phase } = harness(page({ action }));
			actor.start();
			expect(phase()).toBe("waitingForBrowser");
			expect(start).not.toHaveBeenCalled();

			actor.send({ type: "MOUNTED" });
			await waitFor(actor, (s) => s.matches({ payment: "checkout" }));
			expect(start).toHaveBeenCalledOnce();
			expect(actor.getSnapshot().context.session).toEqual({
				clientSecret: "cs_test_secret",
				sessionId: "cs_test_1",
			});
		},
	);

	it("a repeated mount or a fresh view that still pays never POSTs again", async () => {
		const { actor, start, phase } = harness(page());
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ payment: "checkout" }));

		actor.send({ type: "MOUNTED" });
		// The POST's success reloads Phoenix's view, now with a live hold.
		actor.send({ type: "PAGE", page: page({ action: "continue_payment" }) });
		expect(phase()).toBe("checkout");
		expect(start).toHaveBeenCalledOnce();
	});

	it("a refusal shows Phoenix's detail and retries only when asked", async () => {
		const start = vi
			.fn<() => Promise<IntakePaymentStart>>()
			.mockResolvedValueOnce({ ok: false, error: "The workshop is full." })
			.mockResolvedValue(opened);
		const { actor, phase } = harness(page(), start);
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ payment: "refused" }));
		expect(actor.getSnapshot().context.refusal).toBe("The workshop is full.");

		actor.send({ type: "RETRY" });
		expect(phase()).toBe("starting");
		// The refusal stays on screen while the retry runs.
		expect(actor.getSnapshot().context.refusal).toBe("The workshop is full.");
		await waitFor(actor, (s) => s.matches({ payment: "checkout" }));
		expect(actor.getSnapshot().context.refusal).toBeNull();
		expect(start).toHaveBeenCalledTimes(2);
	});

	it("an unexpected failure shows fixed copy, never the error", async () => {
		const { actor } = harness(page(), async () => {
			throw new Error("credential-must-not-render");
		});
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ payment: "refused" }));
		expect(actor.getSnapshot().context.refusal).toBe(START_FAILED);
	});

	it("a hosted hold's redirect leaves the page loading", async () => {
		const { actor } = harness(page(), async () => undefined);
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ payment: "redirecting" }));
		expect(actor.getSnapshot().can({ type: "RETRY" })).toBe(false);
	});

	it("returning to a payment action after the start was spent waits for the person", async () => {
		const { actor, start, phase } = harness(page());
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ payment: "checkout" }));

		actor.send({
			type: "PAGE",
			page: page({ state: "payment_in_progress", action: "check_again" }),
		});
		actor.send({ type: "PAGE", page: page() });
		expect(phase()).toBe("paused");
		expect(start).toHaveBeenCalledOnce();

		actor.send({ type: "RETRY" });
		await waitFor(actor, (s) => s.matches({ payment: "checkout" }));
		expect(start).toHaveBeenCalledTimes(2);
	});

	it("a start that answers after the view moved on is discarded", async () => {
		const answer = deferred<IntakePaymentStart>();
		const { actor, phase } = harness(page(), () => answer.promise);
		actor.start();
		actor.send({ type: "MOUNTED" });
		actor.send({ type: "PAGE", page: page({ state: "paid", action: "none" }) });
		expect(phase()).toBe("settled");

		answer.resolve(opened);
		await Promise.resolve();
		expect(phase()).toBe("settled");
		expect(actor.getSnapshot().context.session).toBeNull();
	});

	it.each(["confirm", "check_again", "none"] as const)(
		"%s never starts a payment",
		(action) => {
			const { actor, start } = harness(page({ action }));
			actor.start();
			actor.send({ type: "MOUNTED" });
			expect(start).not.toHaveBeenCalled();
		},
	);
});

describe("intakePageMachine: the other phases", () => {
	it("a Carried Fee holder's view selects the confirm alternative", () => {
		const { actor, phase } = harness(page({ state: "confirm", action: "confirm" }));
		actor.start();
		expect(phase()).toBe("confirmPlace");

		actor.send({ type: "PAGE", page: page({ state: "paid", action: "none" }) });
		expect(phase()).toBe("settled");
	});

	it("payment_in_progress asks Phoenix again after the delay, re-armed by each new view", () => {
		const inProgress = () =>
			page({ state: "payment_in_progress", action: "check_again" });
		const { actor, refresh, clock, phase } = harness(inProgress());
		actor.start();
		actor.send({ type: "MOUNTED" });
		expect(phase()).toBe("awaitingPayment");

		clock.increment(2999);
		expect(refresh).not.toHaveBeenCalled();
		clock.increment(1);
		expect(refresh).toHaveBeenCalledOnce();
		// The same view does not ask again on its own…
		clock.increment(6000);
		expect(refresh).toHaveBeenCalledOnce();

		// …the next view from Phoenix does.
		actor.send({ type: "PAGE", page: inProgress() });
		clock.increment(3000);
		expect(refresh).toHaveBeenCalledTimes(2);

		actor.send({ type: "PAGE", page: page({ state: "paid", action: "none" }) });
		clock.increment(3000);
		expect(refresh).toHaveBeenCalledTimes(2);
		expect(phase()).toBe("settled");
	});

	it("a server render never refreshes: the timer needs the mounted browser", () => {
		const { actor, refresh, clock } = harness(
			page({ state: "payment_in_progress", action: "check_again" }),
		);
		actor.start();
		clock.increment(3000);
		expect(refresh).not.toHaveBeenCalled();
	});

	it("Check again asks Phoenix once per press", () => {
		const { actor, refresh } = harness(page({ state: "full", action: "check_again" }));
		actor.start();
		actor.send({ type: "REFRESH" });
		expect(refresh).toHaveBeenCalledOnce();
	});

	it("stopping cancels the pending refresh", () => {
		const { actor, refresh, clock } = harness(
			page({ state: "payment_in_progress", action: "check_again" }),
		);
		actor.start();
		actor.send({ type: "MOUNTED" });
		actor.stop();
		clock.increment(3000);
		expect(refresh).not.toHaveBeenCalled();
	});
});

import type { StripeEmbeddedCheckoutOptions } from "@stripe/stripe-js";
import { describe, expect, it, vi } from "vitest";
import { createActor, waitFor } from "xstate";
import {
	embeddedCheckoutWidget,
	type EmbeddedCheckoutWidget,
} from "#lib/stripe/embedded-checkout-widget.js";
import {
	CHECKOUT_FAILED,
	CHECKOUT_MISSING,
	PAYMENT_UNAVAILABLE,
	workshopRegistrationCheckoutMachine,
	workshopRegistrationCheckoutPhase,
	type WorkshopRegistrationCheckoutInput,
} from "./workshop-registration-checkout-machine";

// SAFETY: only the fake widget's `mount` receives the container.
const container = {} as HTMLElement;

function harness(
	input: Partial<WorkshopRegistrationCheckoutInput> = {},
	create?: (
		options: StripeEmbeddedCheckoutOptions,
	) => Promise<EmbeddedCheckoutWidget>,
) {
	const widget = { mount: vi.fn(), destroy: vi.fn() };
	const factory = vi.fn(create ?? (async () => widget));
