const intakePage = `<script lang="ts">
import { onMount, tick, untrack } from "svelte";
import { useMachine } from "@xstate/svelte";
import { fromPromise } from "xstate";
import { goto, invalidateAll } from "$app/navigation";
import IntakeCheckout from "./intake-checkout.svelte";
import { intakeActionLabel, intakeCopy, intakeDetails, REFRESH_MS } from "./intake-page.js";
import { intakePageMachine, intakePagePhase } from "./intake-page-machine.js";
import { confirmIntakePlace, startIntakePayment } from "./intake.remote";

let { page, token, refresh = () => void invalidateAll(), refreshMs = REFRESH_MS, startPayment = submitPayment } = $props();

const formId = $props.id();
const paymentForm = startIntakePayment.for(formId);
const confirmForm = confirmIntakePlace.for(formId);

async function submitPayment() {
	await tick();
	if (!(await paymentForm.submit())) throw new Error("Payment not submitted");
	return paymentForm.result;
}

const { snapshot, send } = useMachine(
	intakePageMachine.provide({
		actors: { startPayment: fromPromise(() => untrack(() => startPayment)()) },
		actions: { refresh: () => untrack(() => refresh)() },
	}),
	{ input: untrack(() => ({ page, refreshMs })) },
);

onMount(() => send({ type: "MOUNTED" }));
$effect(() => {
	send({ type: "PAGE", page });
});

const phase = $derived(intakePagePhase($snapshot));
const session = $derived($snapshot.context.session);
const actionLabel = $derived(intakeActionLabel(page));
const inPayment = $derived(phase === "starting" || phase === "checkout" || phase === "refused");
const refusal = $derived.by(() => {
	if (phase === "confirmPlace") {
		const result = confirmForm.result;
		return result && !result.ok ? result.error : null;
	}
	return inPayment ? $snapshot.context.refusal : null;
});
const retryLabel = $derived(phase === "refused" ? "Try again" : phase === "paused" ? actionLabel : null);
const retrying = $derived(phase === "starting" && !!refusal);
</script>

{#if inPayment}
	{#if phase === "checkout" && session}
		{#key session.clientSecret}
			<IntakeCheckout clientSecret=REDACTED onComplete={() => goto(\`?session_id=\${encodeURIComponent(session.sessionId)}\`)} />
		{/key}
	{:else if phase === "starting" && !retrying}
		<p role="status">Loading secure payment…</p>
	{/if}
	<form {...paymentForm} hidden={!retryLabel && !retrying}>
		<input {...paymentForm.fields.token.as("hidden", token)} />
		<button type="button" disabled={retrying} onclick={() => send({ type: "RETRY" })}>{retrying ? "Loading secure payment…" : retryLabel}</button>
	</form>
{:else if phase === "confirmPlace"}
	<form {...confirmForm}><input {...confirmForm.fields.token.as("hidden", token)} /><button type="submit" disabled={!!confirmForm.pending}>{actionLabel}</button></form>
{:else}
	<button onclick={() => send({ type: "REFRESH" })}>{actionLabel}</button>
{/if}`;
